import type { JSHandle, Page } from '@playwright/test'
import { expect, expectNoAxeViolations, expectNoHorizontalScroll, input, test } from './helpers'

const MESSY =
  'Walters, W.H. & Wilder, E.I (2023) Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports 13(1) 14045 doi:10.1038/s41598-023-41032-5'
const WANTORO =
  'Wantoro, A., et al. (2025). Evaluasi Kinerja Algoritma Machine Learning (ML) Menggunakan Seleksi Fitur Pada Klasifikasi Diabetes. JIP (Jurnal Inform. Polinema), 11(3).'
const BOOK = 'Sugiyono. (2017). Metode penelitian kuantitatif, kualitatif, dan R&D. Bandung: Alfabeta.'

const APA_MESSY =
  'Walters, W. H., & Wilder, E. I. (2023). Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports, 13(1), Article 14045. https://doi.org/10.1038/s41598-023-41032-5'
const IEEE_MESSY =
  '[1] W. H. Walters and E. I. Wilder, "Fabrication and errors in the bibliographic citations generated by ChatGPT," Scientific Reports, vol. 13, no. 1, Art. no. 14045, 2023, doi: 10.1038/s41598-023-41032-5.'
const HARVARD_MESSY =
  "Walters, W.H. and Wilder, E.I. (2023) 'Fabrication and errors in the bibliographic citations generated by ChatGPT', Scientific Reports, 13(1), article 14045. Available at: https://doi.org/10.1038/s41598-023-41032-5."

const list = (page: Page) => page.locator('.fmt-list > li')
const written = (row: ReturnType<typeof list>) => row.locator('.fmt-text').first()
/** The rewritten reference of a row (the second text: the first is what was written). */
const result = (row: ReturnType<typeof list>) => row.locator('.fmt-text').nth(1)
const style = (page: Page, name: string) => page.getByRole('radio', { name })

test.describe('the Format page', () => {
  test('APA is chosen at first, and a careless reference is rewritten with its changes listed', async ({
    page,
  }) => {
    await page.goto('/format')
    await expect(style(page, 'APA 7')).toBeChecked()
    await expect(page.getByText('Paste references on the left.')).toBeVisible()

    await input(page).fill(MESSY)
    await expect(page.getByText('1 reference: 1 rewritten, 0 already match, 0 kept as written.')).toBeVisible()
    const row = list(page).first()
    await expect(row.locator('.fmt-row__status')).toHaveText('Rewritten')
    await expect(written(row)).toHaveText(MESSY)
    await expect(result(row)).toHaveText(APA_MESSY)

    // The journal and the volume are italic, and what changed is underlined.
    await expect(result(row).locator('i').first()).toHaveText('Scientific Reports')
    await expect(result(row).locator('.diff').first()).toBeVisible()

    const changes = row.locator('.fmt-changes li')
    await expect(changes).toHaveCount(4)
    await expect(changes.nth(0)).toContainText('Authors')
    await expect(changes.nth(0)).toContainText('Walters, W.H. & Wilder, E.I')
    await expect(changes.nth(0)).toContainText('Walters, W. H., & Wilder, E. I.')
    await expect(changes.nth(3)).toContainText('https://doi.org/10.1038/s41598-023-41032-5')
  })

  test('switching the style rewrites the same text in IEEE and in Harvard', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(MESSY)
    const row = list(page).first()

    await style(page, 'IEEE').check()
    await expect(result(row)).toHaveText(IEEE_MESSY)
    await expect(result(row).locator('.fmt-label')).toHaveText('[1]')
    await expect(page.getByText('IEEE abbreviates journal names')).toBeVisible()

    await style(page, 'Harvard').check()
    await expect(result(row)).toHaveText(HARVARD_MESSY)
    await expect(page.getByText(/Harvard differs from one university to the next/)).toBeVisible()

    await style(page, 'APA 7').check()
    await expect(result(row)).toHaveText(APA_MESSY)
  })

  test('remembers the style after a reload', async ({ page }) => {
    await page.goto('/format')
    await style(page, 'Harvard').check()
    await page.reload()
    await expect(style(page, 'Harvard')).toBeChecked()
  })

  test('a reference that already matches the style is said to', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(APA_MESSY)
    const row = list(page).first()
    await expect(row.locator('.fmt-row__status')).toHaveText('Already matches APA 7')
    await expect(row.locator('.diff')).toHaveCount(0)
    await expect(row.locator('.fmt-changes')).toHaveCount(0)
  })

  test('a book is kept as written, with the reason', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(BOOK)
    const row = list(page).first()
    await expect(row.locator('.fmt-row__status')).toHaveText('Kept as written')
    await expect(row.locator('.fmt-text')).toHaveText(BOOK)
    await expect(row).toContainText('This is not a journal article that can be read')
    await expect(page.getByText('0 rewritten, 0 already match, 1 kept as written.')).toBeVisible()
  })

  test('sorts APA by the first author, and leaves IEEE in the order given', async ({ page }) => {
    const Z = 'Zulkifli, A. (2020). Judul satu. Jurnal Satu, 1(1), 1-2.'
    const A = 'Aaron, B. (2021). Judul dua. Jurnal Dua, 2(1), 3-4.'
    const M = 'Moreno, G. (2019). Judul tiga. Jurnal Tiga, 3(1), 5-6.'
    await page.goto('/format')
    await input(page).fill(`${Z}\n\n${A}\n\n${M}`)

    await expect(list(page).locator('.fmt-row__num')).toHaveText([
      'Reference 2',
      'Reference 3',
      'Reference 1',
    ])
    await page.getByRole('checkbox', { name: 'Sort by first author (A to Z)' }).uncheck()
    await expect(list(page).locator('.fmt-row__num')).toHaveText([
      'Reference 1',
      'Reference 2',
      'Reference 3',
    ])

    await page.getByRole('checkbox', { name: 'Sort by first author (A to Z)' }).check()
    await style(page, 'IEEE').check()
    await expect(page.getByRole('checkbox', { name: 'Sort by first author (A to Z)' })).toHaveCount(0)
    await expect(list(page).locator('.fmt-row__num')).toHaveText([
      'Reference 1',
      'Reference 2',
      'Reference 3',
    ])
    await expect(list(page).locator('.fmt-label')).toHaveText(['[1]', '[2]', '[3]'])
  })

  test('puts titles into sentence case only when asked, and says so', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(WANTORO)
    const row = list(page).first()
    await expect(result(row)).toContainText('Evaluasi Kinerja Algoritma Machine Learning (ML)')
    await expect(row).toContainText('The title has a capital on almost every word. APA 7 asks for')

    await page.getByRole('checkbox', { name: 'Put titles in sentence case' }).check()
    await expect(result(row)).toContainText('Evaluasi kinerja algoritma machine learning (ML) menggunakan')
    await expect(row).toContainText('The title was put into sentence case.')
    await expect(row).not.toContainText('The title has a capital on almost every word.')
  })

  test('notes that "et al." leaves the other authors unknown', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(WANTORO)
    await expect(list(page).first()).toContainText('The text says "et al." and the other authors are not in it.')
  })

  test('copies a reference with its italics, and as plain text', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write'])
    await page.goto('/format')
    await input(page).fill(MESSY)
    await page.getByRole('button', { name: 'Copy reference 1' }).click()
    await expect(page.getByText('Copied').first()).toBeVisible()

    const clip = await page.evaluate(async () => {
      const out: Record<string, string> = {}
      for (const item of await navigator.clipboard.read()) {
        for (const type of item.types) out[type] = await (await item.getType(type)).text()
      }
      return out
    })
    expect(clip['text/plain']).toBe(APA_MESSY)
    expect(clip['text/html']).toContain('<i>Scientific Reports</i>')
    expect(clip['text/html']).toContain('<i>13</i>(1)')
  })

  test('copies the whole list, with the IEEE numbers', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write'])
    await page.goto('/format')
    await style(page, 'IEEE').check()
    await input(page).fill(`${MESSY}\n\n${WANTORO}`)
    await page.getByRole('button', { name: 'Copy all, plain text' }).click()
    await expect(page.getByText('Copied').first()).toBeVisible()
    // A Windows clipboard turns \n into \r\n.
    const text = (await page.evaluate(() => navigator.clipboard.readText())).replaceAll('\r\n', '\n')
    expect(text.split('\n\n')).toHaveLength(2)
    expect(text.startsWith('[1] W. H. Walters and E. I. Wilder, ')).toBe(true)
    expect(text).toContain('\n\n[2] A. Wantoro et al., ')
  })

  test('sends nothing anywhere while it rewrites', async ({ page }) => {
    await page.goto('/format')
    const requests: string[] = []
    page.on('request', (r) => requests.push(r.url()))
    await input(page).fill(`${MESSY}\n\n${WANTORO}`)
    await style(page, 'IEEE').check()
    await expect(list(page)).toHaveCount(2)
    // A font file may load when the first monospaced text appears. No request goes to the API, and no
    // request carries any of the text.
    const others = requests.filter((u) => !new URL(u).pathname.startsWith('/assets/'))
    expect(others).toEqual([])
    expect(requests.some((u) => /walters|wantoro|10\.1038/i.test(decodeURIComponent(u)))).toBe(false)
  })

  test('takes a file that is chosen or dropped, like the checker, and keeps the page', async ({
    page,
  }) => {
    await page.goto('/format')
    await page.locator('input[type="file"]').setInputFiles({
      name: 'refs.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from(`${MESSY}\n\n${BOOK}`, 'utf8'),
    })
    await expect(page.getByRole('status').filter({ hasText: 'Added 2 references from refs.txt.' })).toBeVisible()
    await expect(list(page)).toHaveCount(2)

    const dataTransfer: JSHandle<DataTransfer> = await page.evaluateHandle((text) => {
      const dt = new DataTransfer()
      dt.items.add(new File([text], 'more.txt', { type: 'text/plain' }))
      return dt
    }, WANTORO)
    await page.dispatchEvent('body', 'dragenter', { dataTransfer })
    await expect(page.locator('.dropzone')).toContainText('Drop to add to your list')
    await page.dispatchEvent('body', 'drop', { dataTransfer })
    await expect(list(page)).toHaveCount(3)
    await expect(page.locator('.dropzone')).toHaveCount(0)
  })

  test('clearing empties the list', async ({ page }) => {
    await page.goto('/format')
    await input(page).fill(MESSY)
    await page.getByRole('button', { name: 'Clear' }).click()
    await expect(input(page)).toHaveValue('')
    await expect(page.getByText('Paste references on the left.')).toBeVisible()
  })

  test('"Try an example" fills five references of different kinds', async ({ page }) => {
    await page.goto('/format')
    await page.getByRole('button', { name: 'Try an example' }).click()
    await expect(list(page)).toHaveCount(5)
    // The Indonesian article is already written the way APA asks.
    await expect(page.getByText('5 references: 3 rewritten, 1 already matches, 1 kept as written.')).toBeVisible()
  })

  test('works in Indonesian', async ({ page }) => {
    await page.goto('/format')
    await page.getByRole('button', { name: 'Switch to Bahasa Indonesia' }).click()
    await expect(page.getByRole('heading', { level: 1 })).toHaveText('Perbaiki penulisan referensi')
    await page.getByRole('textbox', { name: 'Referensi' }).fill(MESSY)
    await expect(
      page.getByText('1 referensi: 1 ditulis ulang, 0 sudah sesuai, 0 dibiarkan seperti yang ditulis.'),
    ).toBeVisible()
    await expect(list(page).first().locator('.fmt-row__status')).toHaveText('Ditulis ulang')
    await expect(page.getByRole('button', { name: 'Salin referensi 1' })).toBeVisible()
    await expectNoAxeViolations(page)
  })

  test('has no accessibility violations with results, and fits a phone', async ({ page }) => {
    await page.goto('/format')
    await page.getByRole('button', { name: 'Try an example' }).click()
    await expect(list(page)).toHaveCount(5)
    await expectNoAxeViolations(page)
    await page.setViewportSize({ width: 375, height: 800 })
    await expectNoHorizontalScroll(page)
  })
})
